CREATE TABLE MasterWorkspace(Id INTEGER PRIMARY KEY CHECK(Id=1),Mode TEXT NOT NULL,Version INTEGER NOT NULL);
INSERT INTO MasterWorkspace VALUES(1,'Demo',1);
CREATE TABLE MasterSkuData(SkuId TEXT PRIMARY KEY,Unit TEXT NOT NULL,Version INTEGER NOT NULL);
INSERT INTO MasterSkuData SELECT Id,'件',1 FROM Skus;
CREATE TABLE MasterShopData(ShopId TEXT PRIMARY KEY,ExternalId TEXT NOT NULL,Enabled INTEGER NOT NULL CHECK(Enabled IN(0,1)),Version INTEGER NOT NULL);
INSERT INTO MasterShopData SELECT Id,Id,1,1 FROM Shops;
CREATE TABLE MasterMappingState(TenantId TEXT NOT NULL,Platform TEXT NOT NULL,ShopId TEXT NOT NULL,ProductId TEXT NOT NULL,VariantId TEXT NOT NULL,Enabled INTEGER NOT NULL CHECK(Enabled IN(0,1)),PRIMARY KEY(TenantId,Platform,ShopId,ProductId,VariantId));
CREATE TABLE MasterHistory(Id TEXT PRIMARY KEY,Entity TEXT NOT NULL,Action TEXT NOT NULL,Actor TEXT NOT NULL,Reason TEXT NOT NULL,CreatedAt TEXT NOT NULL,DataJson TEXT NOT NULL);
CREATE INDEX IX_MasterHistory_Entity ON MasterHistory(Entity,CreatedAt);
CREATE TABLE OpeningDocuments(Id TEXT PRIMARY KEY,Number TEXT NOT NULL UNIQUE,State TEXT NOT NULL,Version INTEGER NOT NULL,CreatedBy TEXT NOT NULL,ApprovedBy TEXT NOT NULL,Reason TEXT NOT NULL,CreatedAt TEXT NOT NULL,LinesJson TEXT NOT NULL);
CREATE TABLE OpeningSkuClaims(SkuId TEXT PRIMARY KEY,DocumentId TEXT NOT NULL REFERENCES OpeningDocuments(Id));
CREATE TABLE WorkerHealth(Name TEXT PRIMARY KEY,LastSeen TEXT NOT NULL,LastSuccess TEXT NOT NULL,LastError TEXT NOT NULL,ConsecutiveErrors INTEGER NOT NULL);
ALTER TABLE DeliveryJobs ADD COLUMN CycleAttempts INTEGER NOT NULL DEFAULT 0;
